buildscript {
    dependencies {
        classpath(fileTree(mapOf("dir" to "lib", "include" to listOf("*.jar"))))
    }
}

plugins {
    `java-library`
    `maven-publish`
    kotlin("jvm") version "2.1.0"
}

group = "com.danawa.search"
version = "1.0.0"

val esVersion = "9.1.2"
val luceneVersion = "10.1.0"  // ES 9.1.2 호환 Lucene 버전

kotlin {
    jvmToolchain(21)
}

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

tasks.compileJava {
    options.encoding = "UTF-8"
    options.isIncremental = true
    options.isFork = true
    options.isFailOnError = false
}

tasks.compileTestJava {
    options.encoding = "UTF-8"
}

repositories {
    mavenCentral()
    mavenLocal()
}

sourceSets {
    main {
        java {
            srcDir("src/main/java")
            exclude("Tester.java")
        }
        kotlin {
            srcDir("src/main/kotlin")
        }
        resources {
            srcDir("src/main/resources")
            exclude("**/**")
        }
    }
    test {
        java {
            srcDir("src/test/java")
        }
        kotlin {
            srcDir("src/test/kotlin")
        }
    }
}

// ES 9.x Entitlement 정책 파일을 JAR에 포함
tasks.jar {
    from("src/main/plugin-metadata") {
        into("plugin-metadata")
    }
}

dependencies {
    testImplementation("junit:junit:4.1+")

    // Kotlin stdlib
    implementation(kotlin("stdlib"))

    // Stable Plugin API (분석 컴포넌트용)
    compileOnly("org.elasticsearch.plugin:elasticsearch-plugin-api:$esVersion")
    compileOnly("org.elasticsearch.plugin:elasticsearch-plugin-analysis-api:$esVersion")
    compileOnly("org.apache.lucene:lucene-analysis-common:$luceneVersion")

    // Classic Plugin API (REST handler/TransportAction용)
    compileOnly("org.elasticsearch:elasticsearch:$esVersion")

    // 유틸리티 의존성 (플러그인 ZIP에 포함)
    implementation("commons-io:commons-io:1.3.2")
    implementation("org.apache.logging.log4j:log4j-core:2.24.3")
    implementation("org.json:json:2019+")
    implementation("org.yaml:snakeyaml:2.2")

    // 테스트용
    testImplementation("org.elasticsearch.plugin:elasticsearch-plugin-api:$esVersion")
    testImplementation("org.elasticsearch.plugin:elasticsearch-plugin-analysis-api:$esVersion")
    testImplementation("org.apache.lucene:lucene-analysis-common:$luceneVersion")
    testImplementation("org.elasticsearch:elasticsearch:$esVersion")
}

val copyToDependencies by tasks.registering(Copy::class) {
    from(configurations.runtimeClasspath) {
        include("json-*", "slf4j-api*", "snakeyaml-*", "commons-io-*", "kotlin-stdlib-*")
    }
    from("src/main/resources") {
        include("*.properties")
        include("*.policy")
        include("*.yml")
    }
    // ES 9.x Entitlement 정책 파일 - 플러그인 루트에 직접 배치
    from("src/main/plugin-metadata") {
        include("entitlement-policy.yaml")
    }
    into(layout.buildDirectory.dir("libs"))
}

val copyJars by tasks.registering(Copy::class) {
    dependsOn(tasks.jar)
    dependsOn(copyToDependencies)
    from(configurations.runtimeClasspath) {
        include("*.jar")
    }
    from(tasks.jar.flatMap { it.archiveFile }) {
        include("*.jar")
    }
    duplicatesStrategy = DuplicatesStrategy.EXCLUDE
    into(layout.buildDirectory.dir("jars"))
}

tasks.build {
    println("BUILDING..")
}

/**
 * gradle 커맨드에서 다음과 같이 테스트 실행 가능
 * ./gradlew --no-daemon test --tests -DLOG_LEVEL=TRACE -DSYSPROP_LAUNCH_FOR_BUILD=false ProductNameAnalysisFilterTest.testFilter
 */
tasks.withType<Test> {
    val launchForBuild = System.getProperty("SYSPROP_LAUNCH_FOR_BUILD")
    val dictSetting = System.getProperty("SYSPROP_TEST_DICTIONARY_SETTING")
    val logLevel = System.getProperty("LOG_LEVEL")

    if ("false" == launchForBuild) {
        systemProperty("SYSPROP_LAUNCH_FOR_BUILD", "false")
        testLogging.showStandardStreams = true
    } else {
        systemProperty("SYSPROP_LAUNCH_FOR_BUILD", "true")
    }

    if (dictSetting.isNullOrEmpty()) {
        systemProperty("SYSPROP_TEST_DICTIONARY_SETTING", "INTERNAL")
    } else {
        systemProperty("SYSPROP_TEST_DICTIONARY_SETTING", dictSetting)
    }

    if (logLevel.isNullOrEmpty()) {
        systemProperty("LOG_LEVEL", System.getProperty("DEBUG") ?: "")
    } else {
        systemProperty("LOG_LEVEL", logLevel)
    }

    systemProperty("SYSPROP_TEST_DICTIONARY_LOAD_EXTRA", System.getProperty("SYSPROP_TEST_DICTIONARY_LOAD_EXTRA") ?: "")
    systemProperty("SYSPROP_SAMPLE_TEXT_PATH", System.getProperty("SYSPROP_SAMPLE_TEXT_PATH") ?: "")
    systemProperty("log4j.configurationFile", System.getProperty("log4j.configurationFile") ?: "")
    systemProperty("file.encoding", "UTF-8")
}

// ES 플러그인 배포용 ZIP 파일 생성
val pluginZip by tasks.registering(Zip::class) {
    dependsOn(copyToDependencies, copyJars)

    archiveBaseName = "analysis-danuri"
    archiveVersion = version.toString()
    destinationDirectory = layout.buildDirectory.dir("distributions")

    from(layout.buildDirectory.dir("libs")) {
        include("**/*")
    }
}

tasks.build.configure {
    dependsOn(copyToDependencies, copyJars, pluginZip)
}

package com.danawa.search.analysis.product

import java.util.function.Predicate
import java.util.function.Supplier

import org.apache.logging.log4j.LogManager
import org.apache.lucene.analysis.Analyzer
import org.elasticsearch.cluster.metadata.IndexNameExpressionResolver
import org.elasticsearch.cluster.node.DiscoveryNodes
import org.elasticsearch.common.io.stream.NamedWriteableRegistry
import org.elasticsearch.common.settings.ClusterSettings
import org.elasticsearch.common.settings.IndexScopedSettings
import org.elasticsearch.common.settings.Settings
import org.elasticsearch.common.settings.SettingsFilter
import org.elasticsearch.features.NodeFeature
import org.elasticsearch.index.analysis.AnalyzerProvider
import org.elasticsearch.index.analysis.TokenFilterFactory
import org.elasticsearch.index.analysis.TokenizerFactory
import org.elasticsearch.indices.analysis.AnalysisModule.AnalysisProvider
import org.elasticsearch.plugins.ActionPlugin
import org.elasticsearch.plugins.AnalysisPlugin
import org.elasticsearch.plugins.Plugin
import org.elasticsearch.rest.RestController
import org.elasticsearch.rest.RestHandler

import com.danawa.search.analysis.product.action.RestReloadDictAction
import com.danawa.search.analysis.product.action.TransportReloadDictAction

import java.util.Collections.singletonMap

class AnalysisProductNamePlugin : Plugin(), AnalysisPlugin, ActionPlugin {

    init {
        logger.trace("init")
    }

    override fun getTokenFilters(): Map<String, AnalysisProvider<TokenFilterFactory>> {
        val extra: MutableMap<String, AnalysisProvider<TokenFilterFactory>> = HashMap()
        extra["product_name"] = AnalysisProvider(::ProductNameAnalysisFilterFactory)
        return extra
    }

    override fun getTokenizers(): Map<String, AnalysisProvider<TokenizerFactory>> {
        return singletonMap("product_name", AnalysisProvider(::ProductNameTokenizerFactory))
    }

    override fun getAnalyzers(): Map<String, AnalysisProvider<AnalyzerProvider<out Analyzer>>> {
        return singletonMap("product_name", AnalysisProvider(::ProductNameAnalyzerProvider))
    }

    override fun getActions(): List<ActionPlugin.ActionHandler<*, *>> {
        return listOf(
            ActionPlugin.ActionHandler(TransportReloadDictAction.TYPE, TransportReloadDictAction::class.java)
        )
    }

    override fun getRestHandlers(
        settings: Settings, namedWriteableRegistry: NamedWriteableRegistry,
        controller: RestController, clusterSettings: ClusterSettings, indexScopedSettings: IndexScopedSettings,
        filter: SettingsFilter, resolver: IndexNameExpressionResolver, nodes: Supplier<DiscoveryNodes>,
        clusterSupportsFeature: Predicate<NodeFeature>
    ): List<RestHandler> {
        val handlers: MutableList<RestHandler> = ArrayList()
        handlers.add(ProductNameAnalysisAction())
        handlers.add(RestReloadDictAction())
        return handlers
    }

    companion object {
        @JvmStatic
        private val logger = LogManager.getLogger(AnalysisProductNamePlugin::class.java)
    }
}

package com.danawa.search.analysis.product

import com.danawa.search.analysis.dict.ProductNameDictionary
import com.danawa.search.analysis.korean.KoreanWordExtractor
import com.danawa.search.analysis.korean.KoreanWordExtractor.ExtractedEntry
import com.danawa.util.CharVector

import org.apache.logging.log4j.LogManager
import org.apache.lucene.analysis.Tokenizer
import org.apache.lucene.analysis.tokenattributes.CharTermAttribute
import org.apache.lucene.analysis.tokenattributes.OffsetAttribute
import org.apache.lucene.analysis.tokenattributes.TokenInfoAttribute
import org.apache.lucene.analysis.tokenattributes.TypeAttribute
import org.apache.lucene.util.AttributeFactory

import java.io.IOException
import java.util.regex.Pattern

class ProductNameTokenizer : Tokenizer {

    private val termAtt = addAttribute(CharTermAttribute::class.java)
    private val tokenAtt = addAttribute(TokenInfoAttribute::class.java)
    private val offsetAtt = addAttribute(OffsetAttribute::class.java)
    private val typeAtt = addAttribute(TypeAttribute::class.java)

    private var baseOffset = 0
    private var position = 0
    private var extLength = 0
    private var readLength = 0
    private var tokenLength = 0
    private var finalOffset = 0

    private var buffer: CharArray? = null
    private var backBuffer = arrayOf(CharArray(IO_BUFFER_SIZE), CharArray(IO_BUFFER_SIZE))
    private var entry: ExtractedEntry? = null
    private var extractor: KoreanWordExtractor? = null
    private var chrCurrent: Char = 0.toChar()
    private var typeCurrent: String? = null
    private var exportTerm: Boolean = false
    private var tabularFull: Boolean = false

    constructor(dictionary: ProductNameDictionary?, exportTerm: Boolean) {
        if (dictionary != null) {
            extractor = KoreanWordExtractor(dictionary)
            tokenAtt.dictionary(dictionary)
        }
        this.exportTerm = exportTerm
    }

    constructor(factory: AttributeFactory) : super(factory)

    protected fun isTokenChar(c1: Int, c2: Int): Boolean {
        return !Character.isWhitespace(c1)
    }

    @Throws(IOException::class)
    override fun incrementToken(): Boolean {
        typeAtt.setType(null)
        logger.trace("INCREMENT-TOKEN")
        var length = 0
        var start = -1
        var end = -1
        var bufferStart = position
        var continueTerm = false
        var startOffset = 0
        var endOffset = 0
        while (!tokenAtt.isState(TokenInfoAttribute.STATE_INPUT_FINISHED)) {
            if (entry == null) {
                while (true) {
                    if (position >= readLength) {
                        ////////////////////////////////////////////////////////////////////////////////
                        // 1. 원본 읽어오기 (버퍼 크기만큼 읽어옴)
                        ////////////////////////////////////////////////////////////////////////////////
                        val oldBuffer = backBuffer[0]
                        val newBuffer = backBuffer[1]
                        backBuffer[0] = newBuffer
                        backBuffer[1] = oldBuffer
                        baseOffset += readLength
                        readLength = input.read(newBuffer, 0, newBuffer.size)
                        logger.trace("READ {}/{}", newBuffer.size, readLength)
                        if (readLength > 0) {
                            buffer = newBuffer
                            tokenAtt.ref(newBuffer, 0, 0)
                            tokenAtt.rmState(TokenInfoAttribute.STATE_INPUT_BUFFER_EXHAUSTED)
                            entry = null
                            tokenLength = readLength
                            while (tokenLength > 0) {
                                if (getType(newBuffer[tokenLength - 1].code) !== WHITESPACE) {
                                    break
                                }
                                tokenLength--
                            }
                        } else {
                            readLength = 0
                            logger.trace("LENGTH:{} / {}", length, readLength)
                            if (length > 0) {
                                break
                            } else {
                                finalOffset = correctOffset(baseOffset)
                                logger.trace("TOKENIZER STOPPED!!")
                                tokenAtt.addState(TokenInfoAttribute.STATE_INPUT_FINISHED)
                                return false
                            }
                        }
                        if (tokenLength > 0 && tokenLength < FULL_TERM_LENGTH && baseOffset == 0) {
                            // FULL-TERM
                            tokenAtt.ref(newBuffer, 0, tokenLength)
                            tokenAtt.posTag(null)
                            offsetAtt.setOffset(0, tokenLength)
                            typeAtt.setType(FULL_STRING)
                            return true
                        }
                        position = 0
                        bufferStart = 0
                        chrCurrent = 0.toChar()
                        typeCurrent = null
                    }
                    run {
                        ////////////////////////////////////////////////////////////////////////////////
                        // 2. 버퍼 내 단순 토크닝
                        ////////////////////////////////////////////////////////////////////////////////
                        val chrPrev = chrCurrent
                        val typePrev = typeCurrent
                        chrCurrent = buffer!![position]
                        typeCurrent = getType(chrCurrent.code)
                        position++
                        var pass = 1

                        if (typePrev == null) {
                            // nop
                        } else if (typePrev === WHITESPACE && typeCurrent !== WHITESPACE) {
                            // nop
                        } else if (typePrev === WHITESPACE && typeCurrent === WHITESPACE) {
                            pass = 2
                        } else if (typePrev !== WHITESPACE && typeCurrent === WHITESPACE) {
                            pass = 0
                        } else if (typePrev !== typeCurrent) {
                            pass = 0
                        }

                        if (pass == 1) {
                            if (length == 0) {
                                assert(start == -1)
                                start = baseOffset + position - 1
                                end = start
                            }
                            end++
                            length++
                            if (position >= tokenLength) {
                                break
                            }
                        } else if (pass == 2) {
                            bufferStart = position
                            return@run
                        } else if (length > 0) {
                            if (position >= tokenLength) {
                                position++
                            }
                            if (typePrev !== WHITESPACE && typeCurrent === WHITESPACE) {
                                position--
                            } else if (typePrev !== WHITESPACE && typeCurrent !== WHITESPACE) {
                                position--
                            }
                            length = position - bufferStart
                            break
                        }
                    }
                }

                assert(start != -1)
                startOffset = correctOffset(start)
                endOffset = correctOffset(end)

                if (extractor != null) {
                    logger.trace("TOKEN:{} / {}~{} / {}", CharVector(buffer, bufferStart, length), position - bufferStart, length)
                    extLength = length
                    if (extLength > extractor!!.tabularSize) {
                        extLength = extractor!!.tabularSize
                        tabularFull = true
                    } else {
                        tabularFull = false
                    }
                    logger.trace("EXTRACT:{} / {}~{} / {}", CharVector(buffer, bufferStart, extLength), bufferStart, extLength, baseOffset)
                    extractor!!.setInput(buffer!!, bufferStart, extLength)
                    entry = extractor!!.extract()
                    continue
                } else {
                    tokenAtt.ref(buffer, bufferStart, length)
                    offsetAtt.setOffset(startOffset, endOffset.also { finalOffset = it })
                    logger.trace("TOKEN:{} / {}~{}", tokenAtt.ref(), startOffset, endOffset)
                }
            } else {
                while (entry != null) {
                    ////////////////////////////////////////////////////////////////////////////////
                    // 3. 한글분해
                    ////////////////////////////////////////////////////////////////////////////////
                    if (entry!!.column() <= 0) {
                        entry = entry!!.next()
                        continue
                    }
                    startOffset = correctOffset(baseOffset + entry!!.offset())
                    endOffset = correctOffset(baseOffset + entry!!.offset() + entry!!.column())
                    tokenAtt.ref(buffer, entry!!.offset(), entry!!.column())
                    tokenAtt.posTag(entry!!.posTag())
                    offsetAtt.setOffset(startOffset, endOffset)
                    logger.trace("TERM:{} / {}~{} / {} / {} / {}", tokenAtt.ref(), startOffset, endOffset, baseOffset, readLength, tokenAtt.posTag())
                    if (exportTerm) {
                        if (logger.isTraceEnabled) {
                            logger.trace("{} / {}~{}", String(buffer!!, entry!!.offset(), entry!!.column()), entry!!.offset(), entry!!.column())
                        }
                        termAtt.copyBuffer(buffer, entry!!.offset(), entry!!.column())
                    }
                    val extPosition0 = entry!!.offset() + entry!!.column()
                    var extPosition = extPosition0
                    val prevOffset = entry!!.offset()
                    entry = entry!!.next()
                    while (entry != null) {
                        if (entry!!.offset() < prevOffset) {
                            entry = entry!!.next()
                        } else {
                            break
                        }
                    }

                    if (entry == null) {
                        if (extPosition < position) {
                            if (tabularFull) {
                                logger.trace("CONTINUE-TERM:{}", tokenAtt.ref())
                                if (tokenAtt.ref().length() != extractor!!.tabularSize) {
                                    extPosition -= tokenAtt.ref().length()
                                    continueTerm = true
                                }
                            }
                            extLength = position - extPosition
                            if (extLength > extractor!!.tabularSize) {
                                extLength = extractor!!.tabularSize
                                tabularFull = true
                            } else {
                                tabularFull = false
                            }
                            logger.trace("EXTRACT:{} / {}~{} / {}", CharVector(buffer, extPosition, extLength), extPosition, extLength, baseOffset)
                            extractor!!.setInput(buffer!!, extPosition, extLength)
                            entry = extractor!!.extract()
                            if (continueTerm) {
                                continue
                            }
                        }
                    }
                    var ep = extPosition0
                    while (ep < tokenLength) {
                        if (getType(buffer!![ep].code) !== WHITESPACE) { break }
                        ep++
                    }
                    if (ep == tokenLength) {
