package org.apache.lucene.analysis.tokenattributes

import com.danawa.search.analysis.dict.ProductNameDictionary
import com.danawa.search.analysis.korean.PosTagProbEntry.PosTag
import com.danawa.util.CharVector
import org.apache.lucene.util.AttributeImpl
import org.apache.lucene.util.AttributeReflector

class TokenInfoAttributeImpl : AttributeImpl(), TokenInfoAttribute {

    private var ref: CharVector? = null
    private var posTag: PosTag? = null
    private var state: Int = 0
    private var baseOffset: Int = 0
    private var dictionary: ProductNameDictionary? = null

    override fun ref(buffer: CharArray, offset: Int, length: Int) {
        ref = CharVector(buffer, offset, length)
    }

    override fun offset(offset: Int, length: Int) {
        ref?.offset(offset)
        ref?.length(length)
    }

    override fun ref(): CharVector? = ref

    override fun posTag(posTag: PosTag?) {
        this.posTag = posTag
    }

    override fun posTag(): PosTag? = posTag

    override fun state(state: Int) {
        this.state = state
    }

    override fun state(): Int = state

    override fun isState(flag: Int): Boolean = (state and flag) != 0

    override fun addState(flag: Int) {
        state = state or flag
    }

    override fun rmState(flag: Int) {
        state = state and flag.inv()
    }

    override fun dictionary(dictionary: ProductNameDictionary?) {
        this.dictionary = dictionary
    }

    override fun dictionary(): ProductNameDictionary? = dictionary

    override fun baseOffset(baseOffset: Int) {
        this.baseOffset = baseOffset
    }

    override fun baseOffset(): Int = baseOffset

    override fun toString(): String = ref.toString()

    override fun copyTo(attr: AttributeImpl) {
        if (attr is TokenInfoAttribute) {
            val target = attr as TokenInfoAttribute
            ref?.let { target.ref(it.array(), it.offset(), it.length()) }
            target.posTag(posTag)
            target.state(state)
            target.dictionary(dictionary)
        }
    }

    override fun clear() {
        ref = CharVector()
        posTag = null
        state = TokenInfoAttribute.STATE_INPUT_READY
    }

    override fun reflectWith(reflector: AttributeReflector) {
        reflector.reflect(TokenInfoAttribute::class.java, "ref", ref)
        reflector.reflect(TokenInfoAttribute::class.java, "posTag", posTag)
        reflector.reflect(TokenInfoAttribute::class.java, "state", state)
        reflector.reflect(TokenInfoAttribute::class.java, "dictionary", dictionary)
    }
}

