    11→    private val types: MutableList<String> = ArrayList()
    12→    private val synonyms: MutableList<List<CharSequence>?> = ArrayList()
    13→    private var synonymAttribute: SynonymAttribute? = null
    14→    private var typeAttribute: TypeAttribute? = null
    15→
    16→    override fun init(tokenStream: TokenStream?) {
    17→        if (tokenStream != null) {
    18→            if (tokenStream.hasAttribute(SynonymAttribute::class.java)) {
    19→                this.synonymAttribute = tokenStream.getAttribute(SynonymAttribute::class.java)
    20→                this.typeAttribute = tokenStream.getAttribute(TypeAttribute::class.java)
    21→            }
    22→        }
    23→        this.extraTerms.clear()
    24→        this.synonyms.clear()
    25→    }
    26→
    27→    override fun clear() {
    28→        this.extraTerms.clear()
    29→        this.synonyms.clear()
    30→    }
    31→
    32→    override fun addExtraTerm(extraTerm: String, type: String, synonyms: List<CharSequence>?) {
    33→        logger.trace("add extra {}", extraTerm)
    34→        this.extraTerms.add(extraTerm)
    35→        this.types.add(type)
    36→        this.synonyms.add(synonyms)
    37→    }
    38→
    39→    override fun iterator(): Iterator<String> {
    40→        return object : MutableIterator<String> {
    41→            override fun hasNext(): Boolean {
    42→                return extraTerms.isNotEmpty()
    43→            }
    44→
    45→            override fun next(): String {
