package org.apache.lucene.analysis.tokenattributes

import org.apache.logging.log4j.LogManager
import org.apache.lucene.analysis.TokenStream
import org.apache.lucene.util.AttributeImpl
import org.apache.lucene.util.AttributeReflector

class ExtraTermAttributeImpl : AttributeImpl(), ExtraTermAttribute {

    private val extraTerms: MutableList<String> = ArrayList()
    private val types: MutableList<String> = ArrayList()
    private val synonyms: MutableList<List<CharSequence>?> = ArrayList()
    private var synonymAttribute: SynonymAttribute? = null
    private var typeAttribute: TypeAttribute? = null

    override fun init(tokenStream: TokenStream?) {
        if (tokenStream != null) {
            if (tokenStream.hasAttribute(SynonymAttribute::class.java)) {
                this.synonymAttribute = tokenStream.getAttribute(SynonymAttribute::class.java)
                this.typeAttribute = tokenStream.getAttribute(TypeAttribute::class.java)
            }
        }
        this.extraTerms.clear()
        this.synonyms.clear()
    }

    override fun clear() {
        this.extraTerms.clear()
        this.synonyms.clear()
    }

    override fun addExtraTerm(extraTerm: String, type: String, synonyms: List<CharSequence>?) {
        logger.trace("add extra {}", extraTerm)
        this.extraTerms.add(extraTerm)
        this.types.add(type)
        this.synonyms.add(synonyms)
    }

    override fun iterator(): Iterator<String> {
        return object : MutableIterator<String> {
            override fun hasNext(): Boolean {
                return extraTerms.isNotEmpty()
            }

            override fun next(): String {
                val term = extraTerms.removeAt(0)
                val type = types.removeAt(0)
                val synonym = synonyms.removeAt(0)
                typeAttribute?.setType(type)
                synonymAttribute?.setSynonyms(synonym)
                return term
            }

            override fun remove() {
                extraTerms.removeAt(0)
            }
        }
    }

    override fun size(): Int = extraTerms.size

    override fun toString(): String = extraTerms.toString()

    override fun hashCode(): Int = extraTerms.hashCode()

    override fun equals(other: Any?): Boolean {
        if (other === this) return true
        if (other is ExtraTermAttributeImpl) {
            if (other.extraTerms.size != extraTerms.size ||
                other.types.size != types.size ||
                other.synonyms.size != synonyms.size) {
                return false
            }
            for (inx in other.types.indices) {
                if (other.types[inx] != types[inx]) return false
            }
            for (inx in other.extraTerms.indices) {
                if (other.extraTerms[inx] != extraTerms[inx]) return false
            }
            for (inx in other.synonyms.indices) {
                if (other.synonyms[inx] != synonyms[inx]) return false
            }
            return true
        }
        return false
    }

    override fun copyTo(target: AttributeImpl) {
        if (target === this) return
        if (target is ExtraTermAttributeImpl) {
            target.extraTerms.clear()
            target.extraTerms.addAll(extraTerms)
            target.types.clear()
            target.types.addAll(extraTerms)
            target.synonyms.clear()
            target.synonyms.addAll(synonyms)
            target.typeAttribute = typeAttribute
            target.synonymAttribute = synonymAttribute
        }
    }

    override fun reflectWith(reflector: AttributeReflector) {
        reflector.reflect(ExtraTermAttribute::class.java, "extraTerms", extraTerms)
        reflector.reflect(ExtraTermAttribute::class.java, "types", types)
        reflector.reflect(ExtraTermAttribute::class.java, "synonyms", synonyms)
        reflector.reflect(ExtraTermAttribute::class.java, "typeAttribute", typeAttribute)
        reflector.reflect(ExtraTermAttribute::class.java, "synonymAttribute", synonymAttribute)
    }

    companion object {
        private val logger = LogManager.getLogger(ExtraTermAttributeImpl::class.java)
    }
}

