package org.apache.lucene.analysis.tokenattributes

import org.apache.lucene.util.AttributeImpl
import org.apache.lucene.util.AttributeReflector

class SynonymAttributeImpl : AttributeImpl, SynonymAttribute {

    private var synonyms: List<CharSequence>? = null

    constructor()

    constructor(synonyms: List<CharSequence>?) {
        this.synonyms = synonyms
    }

    override fun clear() {
        synonyms = null
    }

    override fun equals(other: Any?): Boolean {
        if (other === this) return true
        if (other is SynonymAttributeImpl) {
            return if (this.synonyms == null) other.synonyms == null else this.synonyms == other.synonyms
        }
        return false
    }

    override fun hashCode(): Int = synonyms?.hashCode() ?: 0

    override fun copyTo(target: AttributeImpl) {
        val t = target as SynonymAttribute
        t.setSynonyms(synonyms)
    }

    override fun setSynonyms(synonym: List<CharSequence>?) {
        if (synonym == null || synonym.isEmpty()) {
            this.synonyms = null
        } else {
            this.synonyms = synonym
        }
    }

    override fun getSynonyms(): List<CharSequence>? {
        if (synonyms == null || synonyms!!.isEmpty()) {
            return null
        }
        return synonyms
    }

    override fun toString(): String = synonyms.toString()

    override fun reflectWith(reflector: AttributeReflector) {
        reflector.reflect(SynonymAttribute::class.java, "synonyms", synonyms)
    }
}

