import com.danawa.search.analysis.dict.ProductNameDictionary
import com.danawa.search.analysis.product.AnalysisProductNamePlugin
import com.danawa.util.ContextStore

import org.apache.logging.log4j.LogManager
import org.elasticsearch.action.ActionType
import org.elasticsearch.action.FailedNodeException
import org.elasticsearch.action.support.ActionFilters
import org.elasticsearch.action.support.nodes.TransportNodesAction
import org.elasticsearch.cluster.node.DiscoveryNode
import org.elasticsearch.cluster.service.ClusterService
import org.elasticsearch.common.io.stream.StreamInput
import org.elasticsearch.injection.guice.Inject
import org.elasticsearch.tasks.Task
import org.elasticsearch.threadpool.ThreadPool
import org.elasticsearch.transport.TransportService

import java.io.IOException

class TransportReloadDictAction @Inject constructor(
    threadPool: ThreadPool,
    clusterService: ClusterService,
    transportService: TransportService,
    actionFilters: ActionFilters
) : TransportNodesAction<
    ReloadDictNodesRequest,
    ReloadDictNodesResponse,
    ReloadDictNodeRequest,
    ReloadDictNodeResponse,
    Void>(
    ACTION_NAME,
    clusterService,
    transportService,
    actionFilters,
    ::ReloadDictNodeRequest,
    threadPool.executor(ThreadPool.Names.MANAGEMENT)
) {

    override fun newResponse(
        request: ReloadDictNodesRequest,
        responses: List<ReloadDictNodeResponse>,
        failures: List<FailedNodeException>
    ): ReloadDictNodesResponse {
        return ReloadDictNodesResponse(clusterService.clusterName, responses, failures)
    }

    override fun newNodeRequest(request: ReloadDictNodesRequest): ReloadDictNodeRequest {
        return ReloadDictNodeRequest(request.dictionaryType)
    }

    @Throws(IOException::class)
    override fun newNodeResponse(input: StreamInput, node: DiscoveryNode): ReloadDictNodeResponse {
        return ReloadDictNodeResponse(input)
    }

    override fun nodeOperation(request: ReloadDictNodeRequest, task: Task): ReloadDictNodeResponse {
        val localNode = clusterService.localNode()
        val startTime = System.currentTimeMillis()

        return try {
            logger.info("[{}] Dictionary reload started, type={}", localNode.name, request.dictionaryType)

            if (!contextStore.containsKey(ProductNameDictionary.PRODUCT_NAME_DICTIONARY)) {
                logger.warn("[{}] Dictionary not initialized", localNode.name)
                return ReloadDictNodeResponse(localNode, false, "Dictionary not initialized", 0, 0)
            }

            val dictionary = contextStore.getAs(
                ProductNameDictionary.PRODUCT_NAME_DICTIONARY,
                ProductNameDictionary::class.java
            ) ?: return ReloadDictNodeResponse(localNode, false, "Dictionary instance is null", 0, 0)

            ProductNameDictionary.reloadDictionary()

            val elapsed = System.currentTimeMillis() - startTime
            val size = getDictionarySize(dictionary)

            logger.info("[{}] Dictionary reload completed in {}ms, size={}", localNode.name, elapsed, size)

            ReloadDictNodeResponse(localNode, true, "Reload successful", elapsed, size)
        } catch (e: Exception) {
            val elapsed = System.currentTimeMillis() - startTime
            logger.error("[{}] Dictionary reload failed: {}", localNode.name, e.message, e)
            ReloadDictNodeResponse(localNode, false, e.message, elapsed, 0)
        }
    }

    private fun getDictionarySize(dictionary: ProductNameDictionary): Int {
        return try {
            dictionary.dictionaryMap?.size ?: 0
        } catch (e: Exception) {
            logger.debug("Failed to get dictionary size", e)
            0
        }
    }

    companion object {
        const val ACTION_NAME = "cluster:admin/analysis/dict/reload"

        @JvmField
        val TYPE: ActionType<ReloadDictNodesResponse> = ActionType(ACTION_NAME)

        @JvmStatic
        private val logger = LogManager.getLogger(TransportReloadDictAction::class.java)
        private val contextStore = ContextStore.getStore(AnalysisProductNamePlugin::class.java)
    }
}

