import org.elasticsearch.xcontent.ToXContentFragment
import org.elasticsearch.xcontent.XContentBuilder

import java.io.IOException

class ReloadDictNodeResponse : BaseNodeResponse, ToXContentFragment {

    val isSuccess: Boolean
    val message: String?
    val reloadTimeMs: Long
    val dictionarySize: Int

    constructor(node: DiscoveryNode, success: Boolean, message: String?, reloadTimeMs: Long, dictionarySize: Int) : super(node) {
        this.isSuccess = success
        this.message = message
        this.reloadTimeMs = reloadTimeMs
        this.dictionarySize = dictionarySize
    }

    @Throws(IOException::class)
    constructor(input: StreamInput) : super(input) {
        this.isSuccess = input.readBoolean()
        this.message = input.readOptionalString()
        this.reloadTimeMs = input.readVLong()
        this.dictionarySize = input.readVInt()
    }

    @Throws(IOException::class)
    override fun writeTo(out: StreamOutput) {
        super.writeTo(out)
        out.writeBoolean(isSuccess)
        out.writeOptionalString(message)
        out.writeVLong(reloadTimeMs)
        out.writeVInt(dictionarySize)
    }

    @Throws(IOException::class)
    override fun toXContent(builder: XContentBuilder, params: ToXContentFragment.Params): XContentBuilder {
        builder.field("success", isSuccess)
        if (message != null) {
            builder.field("message", message)
        }
        builder.field("reload_time_ms", reloadTimeMs)
        builder.field("dictionary_size", dictionarySize)
        return builder
    }
}

