class RestReloadDictAction : BaseRestHandler() {

    override fun getName(): String {
        return "reload_dict_action"
    }

    override fun routes(): List<Route> {
        return listOf(
            Route(POST, "/_analysis-product-name/reload-dict"),
            Route(GET, "/_analysis-product-name/reload-dict")
        )
    }

    override fun prepareRequest(request: RestRequest, client: NodeClient): RestChannelConsumer {
        val type = request.param("type")
        val nodesRequest = ReloadDictNodesRequest(type)

        return RestChannelConsumer { channel ->
