package com.danawa.util

import java.util.concurrent.ConcurrentHashMap

class ContextStore private constructor() {

    private val map: MutableMap<String, Any> = ConcurrentHashMap()

    fun containsKey(key: String): Boolean = map.containsKey(key)

    fun put(key: String, obj: Any) {
        map[key] = obj
    }

    fun getDouble(key: String, def: Double?): Double? {
        val obj = map[key] ?: return null
        return if (obj is String) {
            obj.toDouble()
        } else {
            def
        }
    }

    fun getFloat(key: String, def: Float?): Float? {
        val obj = map[key] ?: return null
        return if (obj is String) {
            obj.toFloat()
        } else {
            def
        }
    }

    fun getLong(key: String, def: Long?): Long? {
        val obj = map[key] ?: return null
        return if (obj is String) {
            obj.toLong()
        } else {
            def
        }
    }

    fun getInteger(key: String, def: Int?): Int? {
        val obj = map[key] ?: return null
        return if (obj is String) {
            obj.toInt()
        } else {
            def
        }
    }

    fun getString(key: String, def: String?): String? {
        val obj = map[key] ?: return def
        return obj.toString()
    }

    @Suppress("UNCHECKED_CAST")
    fun <T> getAs(key: String, cls: Class<T>): T? {
        val obj = map[key] ?: return null
        return obj as T
    }

    companion object {
        @JvmStatic
        private val STORE: MutableMap<Class<*>, ContextStore> = ConcurrentHashMap()

        @JvmStatic
        fun getStore(cls: Class<*>?): ContextStore? {
            if (cls != null) {
                return STORE.getOrPut(cls) { ContextStore() }
            }
            return null
        }
    }
}

