    @Throws(IOException::class)
    override fun prepareRequest(request: RestRequest, client: NodeClient): RestChannelConsumer {
        val action = request.param("action")
        val buffer = StringWriter()
        val builder = JSONWriter(buffer)

        if (ACTION_TEST == action) {
            testAction(request, client, builder)
            builder.`object`().key("action").value(action).endObject()
        } else if (ACTION_RELOAD_DICT == action) {
            reloadDictionary()
            builder.`object`().key("action").value(action).endObject()
        } else if (ACTION_INFO_DICT == action) {
            builder.`object`().key("action").value(action)
            infoDictionary(request, client, builder)
            builder.endObject()
        } else if (ACTION_FIND_DICT == action) {
            builder.`object`().key("action").value(action)
            findDictionary(request, client, builder)
            builder.endObject()
        } else if (ACTION_RESTORE_DICT == action) {
            restoreDictionary(request, client)
            builder.`object`().key("action").value(action).endObject()
        } else if (ACTION_COMPILE_DICT == action) {
            compileDictionary(request, client)
            builder.`object`().key("action").value(action).endObject()
        } else if (ACTION_FULL_INDEX == action) {
            val count = bulkIndex(request, client)
            builder.`object`().key("action").value(action)
            if (count > 0) {
                builder.key("working").value("true").key("count").value(count)
            } else {
                builder.key("working").value("false")
            }
            builder.endObject()
        } else if (ACTION_FASTCAT_INDEX == action) {
            val count = fastcatIndex(request, client)
            builder.`object`().key("action").value(action)
            if (count > 0) {
                builder.key("working").value("true").key("count").value(count)
            } else {
                builder.key("working").value("false")
            }
            builder.endObject()
        } else if (ACTION_ANALYZE_TEXT == action) {
            analyzeTextAction(request, client, builder)
        } else if (ACTION_SEARCH == action) {
            search(request, client, builder)
        } else if (ACTION_BUILD_QUERY == action) {
            buildQuery(request, client, builder)
        } else if (ACTION_ANALYZE_MULTI_PARAMS == action) {
            builder.`object`()
            analyzeMultiParamsAction(request, client, builder)
            builder.endObject()
        } else if (ACTION_SYNONYM_LIST == action) {
            builder.`object`()
            getSynonymListAction(request, client, builder)
            builder.endObject()
        } else if (ACTION_SEARCH_KEYWORD == action) {
            makeSearchKeyword(request, client, builder)
        } else if (ACTION_CHECK_ENABLE == action) {
            builder.`object`().key("loaded").value(getDictionary() != null)
            builder.endObject()
        }
        return RestChannelConsumer { channel ->
            channel.sendResponse(RestResponse(RestStatus.OK, CONTENT_TYPE_JSON, BytesArray(buffer.toString().toByteArray(StandardCharsets.UTF_8))))
        }
    }

    private fun parseRequestBody(request: RestRequest): JSONObject {
        var ret = JSONObject()
        try {
            ret = JSONObject(JSONTokener(request.content().utf8ToString()))
        } catch (ignore: Exception) { }
        return ret
    }

