    private fun compileDictionary(request: RestRequest, client: NodeClient) {
        var jparam = JSONObject()
        var index = request.param("index", ES_DICTIONARY_INDEX)
        var type = request.param("type", null as String?)
        var exportFile = request.paramAsBoolean("exportFile", false)
        var distribute = request.paramAsBoolean("distribute", false)
        var host = request.param("host", null as String?)
        var port = request.paramAsInt("port", 9200)
        var username = request.param("username", null as String?)
        var password = request.param("password", null as String?)

        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            index = jparam.optString("index", ES_DICTIONARY_INDEX)
            type = jparam.optString("type", null)
            exportFile = jparam.optBoolean("exportFile", false)
            distribute = jparam.optBoolean("distribute", false)
            host = jparam.optString("host", null)
            port = jparam.optInt("port", 9200)
            username = jparam.optString("username", null)
            password = jparam.optString("password", null)
        } else {
            jparam.put("index", index)
            jparam.put("type", type)
            jparam.put("exportFile", exportFile)
            jparam.put("distribute", distribute)
            jparam.put("host", host)
            jparam.put("port", port)
            jparam.put("username", username)
            jparam.put("password", password)
        }

        val repo: DictionarySource
        if (host != null && "" != host) {
            val remoteNodeClient = RemoteNodeClient(client.settings(), client.threadPool(), ES_DICTIONARY_INDEX, host, port, username, password)
            repo = DictionarySource(remoteNodeClient, index)
        } else {
            repo = DictionarySource(client, index)
        }

        ProductNameDictionary.compileDictionary(client, repo, type, exportFile)
        ProductNameDictionary.reloadDictionary()

        if (distribute) {
            jparam.put("distribute", false)
            distribute(client, ACTION_COMPILE_DICT, jparam, false)
        }
    }

    private fun infoDictionary(request: RestRequest, client: NodeClient, builder: JSONWriter) {
        var jparam = JSONObject()
        var index = request.param("index", ES_DICTIONARY_INDEX)
        var host = request.param("host", null as String?)
        var port = request.paramAsInt("port", 9200)
        var username = request.param("username", null as String?)
        var password = request.param("password", null as String?)

        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            index = jparam.optString("index", ES_DICTIONARY_INDEX)
            host = jparam.optString("host", null)
            port = jparam.optInt("port", 9200)
            username = jparam.optString("username", null)
            password = jparam.optString("password", null)
        }

        val searchMap = SearchUtil.searchData(client, ".dsearch_dict_apply")
        val remoteNodeClient = RemoteNodeClient(client.settings(), client.threadPool(), ES_DICTIONARY_INDEX, host, port, username, password)

        val productNameDictionary = getDictionary()!!
        builder
            .key("dictionary").array()
            .`object`()
            .key(ES_DICT_FIELD_TYPE).value("SYSTEM")
            .key("class").value(TagProbDictionary::class.java.simpleName)
            .key("count").value(productNameDictionary.size())
            .key("label").value(productNameDictionary.label())
            .key("seq").value(productNameDictionary.seq())
            .key("ignoreCase").value(productNameDictionary.ignoreCase())
            .key("tokenType").value("NONE")
            .endObject()
        val dictionaryMap = productNameDictionary.dictionaryMap
        val keySet = dictionaryMap.keys
        for (key in keySet) {
            val typeStr = key.uppercase()
            val sourceDictionary = dictionaryMap[key]!!
            val info = ProductNameDictionary.getDictionaryInfo(sourceDictionary)
            val indexCount: Long
            if (host != null && "" != host) {
                indexCount = SearchUtil.count(remoteNodeClient, index, QueryBuilders.matchQuery(ES_DICT_FIELD_TYPE, typeStr))
            } else {
                indexCount = SearchUtil.count(client as Client, index, QueryBuilders.matchQuery(ES_DICT_FIELD_TYPE, typeStr))
            }

            val id = typeStr.lowercase()
            var count = 0
            var appliedTime = ""
            var updatedTime = ""

            if (searchMap[id] != null) {
                count = searchMap[id] as Int
            }
            if (searchMap[id + "_appliedTime"] != null) {
                appliedTime = searchMap[id + "_appliedTime"] as String
            }
            if (searchMap[id + "_updatedTime"] != null) {
                updatedTime = searchMap[id + "_updatedTime"] as String
            }

            builder.`object`()
                .key(ES_DICT_FIELD_TYPE).value(typeStr)
                .key("class").value(sourceDictionary.javaClass.simpleName)
                .key("dictType").value(sourceDictionary.type().name)
                .key("ignoreCase").value(sourceDictionary.ignoreCase())
                .key("tokenType").value(if (sourceDictionary.tokenType() == null) "NONE" else sourceDictionary.tokenType())
                .key("label").value(sourceDictionary.label())
                .key("seq").value(sourceDictionary.seq())
                .key("id").value(key)
                .key("updatedTime").value(updatedTime)
                .key("appliedTime").value(appliedTime)
                .key("count").value(count)
                .key("indexCount").value(indexCount)

            if (info[1] != 0) {
                builder.key("words").value(info[1])
            }
            builder.endObject()
        }
        builder.endArray()
    }

    private fun findDictionary(request: RestRequest, client: NodeClient, builder: JSONWriter) {
        var jparam = JSONObject()
        var index = request.param("index", ES_DICTIONARY_INDEX)
        var word = request.param("word", "")
        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            index = jparam.optString("index", ES_DICTIONARY_INDEX)
            word = jparam.optString("word", "")
        }

        val productNameDictionary = getDictionary()!!
        val keySet = productNameDictionary.dictionaryMap.keys

        builder.key("result").array()

        val tagProbs = productNameDictionary.find(CharVector.valueOf(word))
        if (tagProbs != null) {
            for (inx in tagProbs.indices) {
                val tagProb = tagProbs[inx]
                builder.`object`()
                    .key(ES_DICT_FIELD_TYPE).value("SYSTEM")
                    .key(ES_DICT_FIELD_KEYWORD).value(word)
                    .key("posTag").value(tagProb.posTag())
                    .key("prob").value(tagProb.prob())
                    .endObject()
            }
        }
        for (type0 in keySet) {
            val type = type0.uppercase()
            val query = QueryBuilders.boolQuery()
                .must(QueryBuilders.matchQuery(ES_DICT_FIELD_TYPE, type))
                .must(QueryBuilders.boolQuery()
                    .should(QueryBuilders.matchQuery(ES_DICT_FIELD_KEYWORD, word))
                    .should(QueryBuilders.matchQuery(ES_DICT_FIELD_VALUE, word))
                )
            val result = SearchUtil.search(client as Client, index, query, null, null, 0, -1, true, null)
            while (result.hasNext()) {
                val data = result.next()
                val keyword = CharVector.valueOf(data[ES_DICT_FIELD_KEYWORD])
                val value = CharVector.valueOf(data[ES_DICT_FIELD_VALUE])
                val id = CharVector.valueOf(data[ES_DICT_FIELD_ID])
                builder.`object`()
                builder.key(ES_DICT_FIELD_TYPE).value(type)
                if (keyword != null && keyword.length() > 0) {
                    builder.key(ES_DICT_FIELD_KEYWORD).value(keyword)
                }
                if (value != null && value.length() > 0) {
                    builder.key(ES_DICT_FIELD_VALUE).value(value)
                }
                if (id != null && id.length() > 0) {
                    builder.key(ES_DICT_FIELD_ID).value(id)
                }
                builder.endObject()
            }
        }
        builder.endArray()
    }

