    class DictionarySource : DictionaryRepository, Iterator<Array<CharSequence>> {
        private var client: Client? = null
        private var remoteClient: RemoteNodeClient? = null
        private var index: String
        private var iterator: Iterator<Map<String, Any>>? = null
        private var remoteResults: MutableList<Map<String, Any>>? = null
        private var remoteIndex: Int = 0

        constructor(client: Client, index: String) {
            this.client = client
            this.index = index
        }

        constructor(remoteClient: RemoteNodeClient, index: String) {
            this.remoteClient = remoteClient
            this.index = index
        }

        override fun getSource(type: String): Iterator<Array<CharSequence>> {
            try {
                val query = QueryBuilders.matchQuery(ES_DICT_FIELD_TYPE, type.uppercase())
                logger.trace("QUERY:{}", query)

                if (remoteClient != null) {
                    remoteResults = ArrayList()
                    remoteIndex = 0
                    val searchRequest = org.elasticsearch.action.search.SearchRequest()
                    val sourceBuilder = org.elasticsearch.search.builder.SearchSourceBuilder()
                    sourceBuilder.query(query).size(10000)
                    searchRequest.indices(index).source(sourceBuilder)

                    val response = remoteClient!!.search(searchRequest)
                    if (response != null && response.has("hits")) {
                        val hits = response.getJSONObject("hits")
                        val hitsArray = hits.getJSONArray("hits")
                        for (i in 0 until hitsArray.length()) {
                            val hit = hitsArray.getJSONObject(i)
                            val source = hit.getJSONObject("_source")
                            val map: MutableMap<String, Any> = HashMap()
                            for (key in source.keySet()) {
                                map[key] = source.get(key)
                            }
                            remoteResults!!.add(map)
                        }
                    }
                } else {
                    iterator = SearchUtil.search(client!!, index, query, null, null, 0, -1, true, null)
                }
            } catch (e: Exception) {
                logger.error("", e)
            }
            return this
        }

        override fun restore(type: String, ignoreCase: Boolean, wordSet: Set<CharSequence>) {
            if (client == null) {
                logger.warn("restore() is not supported for RemoteNodeClient")
                return
            }
            var source: MutableMap<String, Any>?
            var builder: BulkRequestBuilder?
            try {
                builder = client!!.prepareBulk()
                var inx = 0
                for (data in wordSet) {
                    val words = data.toString().split(TAB.toRegex()).toTypedArray()
                    source = HashMap()
                    source[ES_DICT_FIELD_TYPE] = type.uppercase()
                    if (words.size == 1) {
                        source[ES_DICT_FIELD_KEYWORD] = words[0]
                    } else if (words.size == 2) {
                        if (words[0].isNotEmpty()) {
                            source[ES_DICT_FIELD_KEYWORD] = words[0]
                        }
                        source[ES_DICT_FIELD_VALUE] = words[1]
                    } else {
                        source[ES_DICT_FIELD_KEYWORD] = words[0]
                        source[ES_DICT_FIELD_VALUE] = words[1]
                        source[ES_DICT_FIELD_ID] = words[2]
                    }
                    builder!!.add(client!!.prepareIndex(index).setSource(source))
                    if (inx > 0 && inx % 1000 == 0) {
                        builder.execute().actionGet()
                        builder = client!!.prepareBulk()
                    }
                    inx++
                }
                if (inx > 0) {
                    builder!!.execute().actionGet()
                }
            } catch (e: Exception) {
                logger.error("", e)
            }
        }

        override fun hasNext(): Boolean {
            if (remoteClient != null) {
                return remoteResults != null && remoteIndex < remoteResults!!.size
            }
            return iterator != null && iterator!!.hasNext()
        }

        override fun next(): Array<CharSequence> {
            val data: Map<String, Any>
            if (remoteClient != null) {
                data = remoteResults!![remoteIndex++]
            } else {
                data = iterator!!.next()
            }
            val id = CharVector.valueOf(data[ES_DICT_FIELD_ID])
            val keyword = CharVector.valueOf(data[ES_DICT_FIELD_KEYWORD])
            val value = CharVector.valueOf(data[ES_DICT_FIELD_VALUE])
            return arrayOf(id, keyword, value)
        }

        override fun close() {}
    }

