        private fun setAnalyzeSynonym(dictionary: SynonymDictionary, combineTerm: String, client: NodeClient?, index: String?,
            result: MutableMap<String, MutableList<MutableList<String>>>, synonymWayMap: MutableMap<String, Boolean>,
            synonymMap: MutableMap<String, MutableList<String>>, wordsIn: MutableList<String>?, words2In: MutableList<String>?,
            wordListIn: MutableList<MutableList<String>>?, setName: String?, useForQuery: Boolean) {
