        private fun getAnalyzeSynonym(combineTerm: String, useforQuery: Boolean): List<CharSequence> {
            val result: MutableList<CharSequence> = ArrayList()
            try {
                val analyzerStream = ProductNameAnalyzerProvider.getAnalyzer(combineTerm, true, true, true, true, false)
                val synAtr = analyzerStream.addAttribute(SynonymAttribute::class.java)
                val typeAttr = analyzerStream.addAttribute(TypeAttribute::class.java)
                analyzerStream.reset()
                while (analyzerStream.incrementToken()) {
                    val synonyms = synAtr.synonyms
                    if (synonyms != null && synonyms.isNotEmpty()) {
                        for (synonym in synonyms) {
                            val type = typeAttr.type()
                            if (type == ProductNameTokenizer.FULL_STRING && useforQuery) {
                                result.add(synonym)
                            } else if (!useforQuery) {
                                result.add(synonym)
                            }
                        }
                    }
                }
            } catch (e: Exception) {
                logger.error("", e)
            }
            return result
        }

        @JvmStatic
        fun analyzeTextDetailWriteJSON(client: NodeClient?, text: String, stream: TokenStream, index: String, detail: Boolean, writer: JSONWriter, useForQuery: Boolean) {
            val result: MutableMap<String, MutableList<MutableList<String>>> = HashMap()
            val synonymWayMap: MutableMap<String, Boolean> = HashMap()
            val synonymMap: MutableMap<String, MutableList<String>> = HashMap()
            analyzeTextDetail(client, text, stream, index, result, synonymWayMap, synonymMap, useForQuery)

            try {
                writer.`object`()
                    .key("query").value(text)
                    .key("result").array()
                if (detail) {
                    for (key in TreeSet(result.keys)) {
                        val label = ANALYSIS_RESULT_LABELS[key]
                        val wordList = result[key]
                        logger.trace("TYPE:{} / {}", label, wordList)
                        val analyzed = StringBuilder()

                        if (ANALYZE_SET_FULL_STRING == key) {
                            if (wordList != null && wordList.isNotEmpty()) {
                                val words = wordList[0]
                                if (words.isNotEmpty()) { analyzed.append(words[0]) }
                            }
                        } else if (ANALYZE_SET_STOPWORD == key) {
                            for (item in wordList!!) {
                                if (analyzed.isNotEmpty()) { analyzed.append(COMMA).append(" ") }
                                if (item.isNotEmpty()) { analyzed.append(item[0]) }
                            }
                        } else if (ANALYZE_SET_MODEL_NAME == key) {
                            for (item in wordList!!) {
                                if (analyzed.isNotEmpty()) { analyzed.append(TAG_BR) }
                                val fullTermKeyword = item[0]
                                item.removeAt(0)
                                item.add(fullTermKeyword)
                                for (inx in item.indices) {
                                    val w = item[inx]
                                    if (inx == 0) {
                                        analyzed.append(TAG_STRONG.replace(REGEX_TAG_TEXT.toRegex(), Matcher.quoteReplacement(fullTermKeyword)))
                                            .append(" ( ")
                                        analyzed.append(w)
                                    } else {
                                        if (inx > 0) { analyzed.append(", ") }
                                        analyzed.append(w)
                                    }
                                }
                                analyzed.append(" ) ")
                            }
                        } else if (ANALYZE_SET_UNIT == key) {
                            for (item in wordList!!) {
                                if (analyzed.isNotEmpty()) { analyzed.append(TAG_BR) }
                                var word: String? = null
                                val data = StringBuilder()
                                for (inx in item.indices) {
                                    val w = item[inx]
                                    if (inx == 0) {
                                        word = w
                                        analyzed.append(TAG_STRONG.replace(REGEX_TAG_TEXT.toRegex(), Matcher.quoteReplacement(w))).append(" : ")
                                    } else {
                                        if (inx > 1) { data.append(", ") }
                                        data.append(w)
                                    }
                                }
                                if (synonymWayMap.containsKey(word)) {
                                    analyzed.append(data).append(TAG_BR).append(" >>> 동의어 : ")
                                    val synData = StringBuilder()
                                    val synWords = synonymMap[word]!!
                                    for (inx in 1 until synWords.size) {
                                        if (inx > 1) { synData.append(", ") }
                                        synData.append(synWords[inx])
                                    }
                                    analyzed.append(synData)
                                } else {
                                    analyzed.append(data)
                                }
                            }
                        } else if (ANALYZE_SET_NORMAL == key) {
                            for (item in wordList!!) {
                                if (analyzed.isNotEmpty()) { analyzed.append(COMMA).append(" ") }
                                if (item.isNotEmpty()) { analyzed.append(item[0]) }
                            }
                        } else if (ANALYZE_SET_SYNONYM == key) {
                            for (item in wordList!!) {
                                if (analyzed.isNotEmpty()) { analyzed.append(TAG_BR) }
                                var word: String? = null
                                val data = StringBuilder()
                                for (inx in item.indices) {
                                    val w = item[inx]
                                    if (inx == 0) {
                                        word = w
                                        analyzed.append(TAG_STRONG.replace(REGEX_TAG_TEXT.toRegex(), Matcher.quoteReplacement(w))).append(" : ")
                                    } else {
                                        if (inx > 1) { data.append(", ") }
                                        data.append(w)
                                    }
                                }
                                if (synonymWayMap.containsKey(word) && synonymWayMap[word] == true) {
                                    analyzed.append(data).append(TAG_BR).append(" >>> 단방향 : ").append(data)
                                } else {
                                    analyzed.append(data)
                                }
                            }
                        } else if (ANALYZE_SET_COMPOUND == key) {
                            for (item in wordList!!) {
                                if (analyzed.isNotEmpty()) { analyzed.append(TAG_BR) }
                                for (inx in item.indices) {
                                    val w = item[inx]
                                    if (inx == 0) {
                                        analyzed.append(TAG_STRONG.replace(REGEX_TAG_TEXT.toRegex(), Matcher.quoteReplacement(w))).append(" : ")
                                    } else {
                                        if (inx > 1) { analyzed.append(", ") }
                                        analyzed.append(w)
                                    }
                                }
                            }
                        } else if (ANALYZE_SET_FINAL == key) {
                            for (item in wordList!!) {
                                if (analyzed.isNotEmpty()) { analyzed.append(COMMA).append(" ") }
                                if (item.isNotEmpty()) { analyzed.append(item[0]) }
                            }
                        }
                        writer.`object`()
                            .key("key").value(label)
                            .key("value").value(analyzed)
                        writer.endObject()
                    }
                } else {
                    val wordList = result[ANALYZE_SET_FINAL]
                    logger.trace("RESULT:{}", wordList)
                    for (item in wordList!!) {
                        if (item.isNotEmpty()) { writer.value(item[0]) }
                    }
                }
                writer.endArray()
                    .key("success").value(true)
                    .endObject()
            } catch (e: Exception) {
                logger.error("", e)
            }
        }

        @JvmStatic
        fun expansionKeyword(text: String, stream: TokenStream, writer: JSONWriter) {
            // NOTE: This method is a large, complex expansion keyword builder.
            // Simplified to delegate to the Java version pattern.
            val termAttr = stream.addAttribute(CharTermAttribute::class.java)
            val typeAttr = stream.addAttribute(TypeAttribute::class.java)
            val extAttr = stream.addAttribute(ExtraTermAttribute::class.java)
            val synAttr = stream.addAttribute(SynonymAttribute::class.java)
            val offAttr = stream.addAttribute(OffsetAttribute::class.java)

            val tempTermList: MutableList<String> = ArrayList()
            val hash: MutableMap<String, Any> = LinkedHashMap()
            val combineTermSynonym: MutableMap<String, Any> = HashMap()

            var offset = intArrayOf(0, 0)
            var offsetPrev: IntArray
            val dictionary = getDictionary()!!
            val synonymDict = dictionary.getDictionary(ProductNameDictionary.DICT_SYNONYM, SynonymDictionary::class.java)

            try {
                stream.reset()
                while (stream.incrementToken()) {
                    offsetPrev = intArrayOf(offset[0], offset[1])
                    val term = termAttr.toString()
                    var termWords: MutableList<Any> = ArrayList()
                    val extraTermWords: MutableList<Any> = ArrayList()
                    val type = typeAttr.type()
                    offset = intArrayOf(offAttr.startOffset(), offAttr.endOffset())
                    logger.trace("TERM:{} / {}", term, type)

                    if (type == ProductNameTokenizer.FULL_STRING) {
                        val synonyms = synAttr.synonyms
                        if (synonyms != null && synonyms.isNotEmpty()) {
                            termWords = ArrayList()
                            val termList = divideTerm(text)
                            termWords.add(termList)
                            logger.trace("FULLTERM SYNONYM {} / {} ", term, synonyms)
                            for (synonym in synonyms) {
                                val s = synonym.toString()
                                val synonymList = s.split(" ".toRegex()).toTypedArray()
                                if (synonymList.size > 1) { termWords.add(synonymList) } else { termWords.add(s) }
                            }
                            combineTermSynonym[term] = termWords
                        }
                    } else {
                        tempTermList.add(term)
                        if (offset[0] < offsetPrev[1]) {
                            termWords.add(term)
                            offset = intArrayOf(offsetPrev[0], offsetPrev[1])
                        } else {
                            termWords.add(term)
                        }

                        val synonyms = synAttr.synonyms
                        if (synonyms != null && synonyms.isNotEmpty()) {
                            logger.trace("SYNONYM {} / {} ", term, synonyms)
                            for (synonym in synonyms) {
                                val s = synonym.toString()
                                val synonymList = s.split(" ".toRegex()).toTypedArray()
                                if (synonymList.size > 1) { termWords.add(synonymList) } else { termWords.add(s) }
                            }
                        }

                        val iter = extAttr.iterator()
                        if (iter != null && iter.hasNext()) {
                            while (iter.hasNext()) {
                                val s = iter.next()
                                logger.trace("EXT {} / {} / {}", term, s, termWords)
                                extraTermWords.add(s)
                                val extSynonyms = synAttr.synonyms
                                if (extSynonyms != null && extSynonyms.isNotEmpty()) {
                                    val extensionSynonym: MutableMap<String, Any> = HashMap()
                                    val extSynonymList: MutableList<String> = ArrayList()
                                    extraTermWords.remove(s)
                                    logger.trace("EXT-SYN {} / {} / {}", term, s, extSynonyms)
                                    for (synonym in extSynonyms) {
                                        logger.trace("synonym : {}", synonym)
                                        extSynonymList.add(synonym.toString())
                                    }
                                    logger.trace("synonymList : {} - {}", s, extSynonymList)
                                    extensionSynonym[s] = extSynonymList
                                    if (extensionSynonym.isNotEmpty()) { extraTermWords.add(extensionSynonym) }
                                }
                            }
                        }
                        if (extraTermWords.isNotEmpty()) { termWords.add(extraTermWords) }
                    }
                    logger.trace("term : {} - {}", term, termWords)

                    if (termWords.isEmpty()) {
                        combineTermSynonym[term] = arrayOf<Any>(term)
                    } else {
                        if (type != ProductNameTokenizer.FULL_STRING) {
                            hash[term] = termWords.toTypedArray()
                        }
                    }
                }

                if (tempTermList.size > 1) {
                    var prevTerm: String? = null
                    var prePrevTerm: String? = null
                    for (term in tempTermList) {
                        if (prevTerm != null) {
                            val combineTermTwo = prevTerm + term
                            putSynonymData(combineTermSynonym, synonymDict, combineTermTwo)
                            if (prePrevTerm != null) {
                                val combineTermThree = prePrevTerm + combineTermTwo
                                putSynonymData(combineTermSynonym, synonymDict, combineTermThree)
                            }
                        }
                        prePrevTerm = prevTerm
                        prevTerm = term
                    }
                }

                writer.`object`()
                    .key("query").value(text)
                    .key("result").value(hash)
                    .key("synonym").value(combineTermSynonym)
                    .endObject()
            } catch (e: Exception) {
                logger.error("", e)
            }
        }

        private fun putSynonymData(combineTermSynonym: MutableMap<String, Any>, synonymDict: SynonymDictionary, combineTerm: String) {
            val dictData = synonymDict.get(CharVector(combineTerm))
            if (dictData != null) {
                combineTermSynonym[combineTerm] = removeDuplicates(findSynonymTerm(combineTerm, dictData))
            }
        }

        private fun findSynonymTerm(combineTerm: String, dictData: Array<CharSequence>): ArrayList<Any> {
            val result = ArrayList<Any>()
            result.add(divideTerm(combineTerm))
            for (v in dictData) {
                val value = v.toString()
                try {
                    val analyzerStream = ProductNameAnalyzerProvider.getAnalyzer(value, true, false, false, false, false)
                    val termAtr = analyzerStream.addAttribute(CharTermAttribute::class.java)
                    analyzerStream.reset()
                    val subResult = ArrayList<Any>()
                    while (analyzerStream.incrementToken()) {
                        subResult.add(termAtr.toString())
                    }
                    result.add(subResult)
                } catch (e: Exception) {
                    logger.error("", e)
                }
            }
            return result
        }

        private fun divideTerm(keyword: String): ArrayList<Any> {
            val result = ArrayList<Any>()
            try {
                val analyzerStream = ProductNameAnalyzerProvider.getAnalyzer(keyword, true, false, false, false, false)
                val termAtr = analyzerStream.addAttribute(CharTermAttribute::class.java)
                analyzerStream.reset()
                while (analyzerStream.incrementToken()) {
                    result.add(termAtr.toString())
                }
            } catch (e: Exception) {
                logger.error("", e)
            }
            return result
        }

        private fun <T> removeDuplicates(list: ArrayList<T>): ArrayList<T> {
            val newList = ArrayList<T>()
            for (element in list) {
                if (!newList.contains(element)) { newList.add(element) }
            }
            return newList
        }

        @JvmStatic
        fun analyzeMultiParamsText(client: NodeClient?, text: String, stream: TokenStream, index: String, useForQuery: Boolean): List<String> {
            val resultList: MutableList<String> = ArrayList()
            val result: MutableMap<String, MutableList<MutableList<String>>> = HashMap()
            val synonymWayMap: MutableMap<String, Boolean> = HashMap()
            val synonymMap: MutableMap<String, MutableList<String>> = HashMap()
            analyzeTextDetail(client, text, stream, index, result, synonymWayMap, synonymMap, useForQuery)
            try {
                val wordList = result[ANALYZE_SET_FINAL]
                logger.trace("RESULT:{}", wordList)
                for (item in wordList!!) {
                    if (item.isNotEmpty()) { resultList.add(item[0]) }
                }
            } catch (e: Exception) {
                logger.error("", e)
            }
            return resultList
        }

        private fun setAnalyzedResult(result: MutableMap<String, MutableList<MutableList<String>>>, term: String, vararg types: String) {
            for (type in types) {
                val wordList = result[type]!!
                val words: MutableList<String> = ArrayList()
                wordList.add(words)
                words.add(term)
            }
        }

        @JvmStatic
        fun getSynonymList(text: String, stream: TokenStream, writer: JSONWriter) {
            val termAttr = stream.addAttribute(CharTermAttribute::class.java)
            val typeAttr = stream.addAttribute(TypeAttribute::class.java)
            val synAttr = stream.addAttribute(SynonymAttribute::class.java)
            val result: MutableMap<String, MutableList<MutableList<String>>> = HashMap()
            for (key in ANALYSIS_RESULT_LABELS.keys) {
                result[key] = ArrayList()
            }
            var term: String
            var type: String?
            var setName: String?
            try {
                stream.reset()
                while (stream.incrementToken()) {
                    term = termAttr.toString()
                    type = typeAttr.type()
                    logger.trace("TERM:{} / {}", term, type)
                    if (ProductNameTokenizer.FULL_STRING == type) {
                        setName = ANALYZE_SET_FULL_STRING
                        setAnalyzedResult(result, term, ANALYZE_SET_FULL_STRING, ANALYZE_SET_FINAL)
                    } else if (ProductNameTokenizer.MODEL_NAME == type) {
                        setName = ANALYZE_SET_MODEL_NAME
                        setAnalyzedResult(result, term, ANALYZE_SET_MODEL_NAME, ANALYZE_SET_FINAL)
                    } else {
                        setName = ANALYZE_SET_NORMAL
                        setAnalyzedResult(result, term, ANALYZE_SET_NORMAL, ANALYZE_SET_FINAL)
                    }

                    if (ANALYZE_SET_FULL_STRING != setName) {
                        val synonyms = synAttr.synonyms
                        if (synonyms != null && synonyms.isNotEmpty()) {
                            if (term == text) {
                                for (synonym in synonyms) {
                                    writer.value(synonym.toString())
                                }
                            }
                        }
                    }
                }
            } catch (e: Exception) {
                logger.error("", e)
            }
        }

        private fun getDictionary(): ProductNameDictionary? {
            return contextStore.getAs(ProductNameDictionary.PRODUCT_NAME_DICTIONARY, ProductNameDictionary::class.java)
        }
    }
}

