class AnalyzerOption @JvmOverloads constructor(
    private var useForQuery: Boolean = false,
    private var useSynonym: Boolean = true,
    private var useStopword: Boolean = true,
    private var useFullString: Boolean = false,
    private var toUppercase: Boolean = false
) {

    /** 질의용 / 색인용 구분 */
    fun useForQuery(forQuery: Boolean) { this.useForQuery = forQuery }
    fun useForQuery(): Boolean = this.useForQuery

    /** 동의어 사용여부 구분 */
    fun useSynonym(): Boolean = useSynonym
    fun useSynonym(useSynonym: Boolean) { this.useSynonym = useSynonym }

    /** 금지어 사용여부 구분 */
    fun useStopword(): Boolean = useStopword
    fun useStopword(useStopword: Boolean) { this.useStopword = useStopword }

    /** 전체단어 사용여부 구분 */
    fun useFullString(): Boolean = useFullString
    fun useFullString(useFullString: Boolean) { this.useFullString = useFullString }

    /** 대문자 변환 여부 */
    fun toUppercase(): Boolean = toUppercase
    fun toUppercase(toUppercase: Boolean) { this.toUppercase = toUppercase }

    override fun toString(): String = "[$useForQuery,$useSynonym,$useStopword,$useFullString,$toUppercase]"
}
